#include "model.hpp"
#include <iostream>
int main(int argc,char**argv){try{fs::path folder=argv[1],inputs=argv[2];auto protocol=read(inputs/"PROTOCOL.json");Json checks=Json::array();bool all=true;int complete=0;for(auto&level:protocol["levels"]){std::string name=level;auto dir=folder/"results"/name;if(!fs::exists(dir/"result.json"))continue;auto r=read(dir/"result.json"),opt=read(dir/"optimizer.json"),scene=read(inputs/"assets"/name/"scene.json");int n=r["nodes"],w=scene["windows"].size(),width=17+2*w;auto z=opt["x"].get<std::vector<double>>();bool shape=n==400&&int(z.size())==14+w+n*width&&r["states"].size()==n+1&&r["controls"].size()==n&&r["progress"].size()==n+1;double packed=0,originalViolation=0,progressViolation=0;double epsilon=r["stages"].back()["epsilon"],T=r["nominal_time_s"];if(shape){for(int i=0;i<n;++i){int start=14+w+i*width;for(int k=0;k<4;++k)packed=std::max(packed,std::abs(z[start+k]-r["controls"][i][k].get<double>()));for(int k=0;k<13;++k)packed=std::max(packed,std::abs(z[start+4+k]-r["states"][i+1][k].get<double>()));Vector p(z[start+4],z[start+5],z[start+6]);for(int j=0;j<w;++j){Window gate=load_window(scene["windows"][j]);double d2=(p-gate.center-gate.rotation*gate.motion((i+1)*T/n)).squaredNorm();double lambda=z[start+17+j],mu=z[start+17+w+j],tau=std::min(d2,.09),product=lambda*(d2-tau);originalViolation=std::max({originalViolation,-lambda,lambda-1.,-tau,tau-.09,-product,product-epsilon});packed=std::max(packed,std::abs(mu-r["progress"][i+1][j].get<double>()));progressViolation=std::max(progressViolation,std::abs(r["progress"][i][j].get<double>()-lambda-mu));}}}bool found=r["found"],passed=shape&&packed<1e-12&&(!found||(originalViolation<=1.01e-7&&progressViolation<=1.01e-7));all=all&&passed;++complete;checks.push_back({{"level",name},{"passed",passed},{"reported_found",found},{"packing_max_error",packed},{"reconstructed_author_tau_constraint_violation",originalViolation},{"progress_equality_violation",progressViolation}});}save(folder/"RESULT_INTEGRITY.json",{{"completed",complete},{"passed",all},{"checks",checks},{"scope","Packing and original CPC tau feasibility reconstruction; separate from task safety"}});std::cout<<complete<<" checked, integrity="<<all<<'\n';return all?0:1;}catch(std::exception&e){std::cerr<<e.what()<<'\n';return 2;}}
